class Solution {
public:
    int catchMaximumAmountofPeople(vector<int>& team, int dist) {
        vector<int> ones, zeros;
        for (int i = 0; i < (int)team.size(); ++i) {
            if (team[i] == 1) ones.push_back(i);
            else zeros.push_back(i);
        }
        int i = 0, j = 0, answer = 0;
        while (i < (int)ones.size() && j < (int)zeros.size()) {
            if (abs(ones[i] - zeros[j]) <= dist) {
                ++answer;
                ++i;
                ++j;
            } else if (ones[i] < zeros[j]) {
                ++i;
            } else {
                ++j;
            }
        }
        return answer;
    }
};
